-- bank-seed del 2 av 8. Klistra in allt och kör (Run). Kör delarna i ordning.
begin;
insert into public.exercises (id, block_type, title, duration_minutes_default, summary, how_to, watch_for, watch_for_required, safety_line, visual_key, difficulty, tags, default_station_equipment, legacy_equipment, progression_of, regression_of, experienced_coach_only, new_coach_ok, needs_coach_review, source, sort_order, updated_by) values ('warm-uppvarmningsdans', 'warmup', 'Uppvärmningsdans', 6, 'Dansuppvärmning som rör hela kroppen — rörlighet och glädje, inte maxpuls.', '1. Sätt på musik.
2. Led eller använd en känd uppvärmningsdans.
3. Sikta på axlar, höfter, rygg, ben och koordination.
4. Erbjud en enklare, mindre ”scenisk” variant åt den som behöver.', 'För vilda hopp på hårt golv; ge alternativ för den som inte vill dansa sceniskt.', true, 'Inga vilda hopp på hårt golv. Erbjud en lugnare variant.', 'warm-dance', 'intro', array['uppvärmning', 'group', 'equipment-free', 'new-coach-ok']::text[], null, null, null, null, false, true, false, null, 70, 'seed-script') on conflict (id) do update set block_type = excluded.block_type, title = excluded.title, duration_minutes_default = excluded.duration_minutes_default, summary = excluded.summary, how_to = excluded.how_to, watch_for = excluded.watch_for, watch_for_required = excluded.watch_for_required, safety_line = excluded.safety_line, visual_key = excluded.visual_key, difficulty = excluded.difficulty, tags = excluded.tags, default_station_equipment = excluded.default_station_equipment, legacy_equipment = excluded.legacy_equipment, progression_of = excluded.progression_of, regression_of = excluded.regression_of, experienced_coach_only = excluded.experienced_coach_only, new_coach_ok = excluded.new_coach_ok, needs_coach_review = excluded.needs_coach_review, source = excluded.source, sort_order = excluded.sort_order, updated_by = excluded.updated_by;
insert into public.exercises (id, block_type, title, duration_minutes_default, summary, how_to, watch_for, watch_for_required, safety_line, visual_key, difficulty, tags, default_station_equipment, legacy_equipment, progression_of, regression_of, experienced_coach_only, new_coach_ok, needs_coach_review, source, sort_order, updated_by) values ('warm-123-voltpositioner', 'warmup', '1-2-3 (voltpositioner)', 4, 'Positionerna 1, 2 och 3 inför framåtvolt / frivolt-arbete — kort formträning utan full volt.', '1. Gå igenom de tre positionerna ni använder i klubben för framåtvolt.
2. Låt gymnasterna öva dem rytmiskt, samma språk varje gång.
3. Håll det kort — ingen full volt i uppvärmningen om ni bara övar formerna.', 'Tydlighet i språket så alla menar samma position; ingen full volt här om målet bara är formerna.', true, 'Ingen full volt här — bara formerna.', 'warm-123-volt', 'easy', array['uppvärmning', 'group', 'floor', 'new-coach-ok']::text[], null, null, null, null, false, true, true, null, 80, 'seed-script') on conflict (id) do update set block_type = excluded.block_type, title = excluded.title, duration_minutes_default = excluded.duration_minutes_default, summary = excluded.summary, how_to = excluded.how_to, watch_for = excluded.watch_for, watch_for_required = excluded.watch_for_required, safety_line = excluded.safety_line, visual_key = excluded.visual_key, difficulty = excluded.difficulty, tags = excluded.tags, default_station_equipment = excluded.default_station_equipment, legacy_equipment = excluded.legacy_equipment, progression_of = excluded.progression_of, regression_of = excluded.regression_of, experienced_coach_only = excluded.experienced_coach_only, new_coach_ok = excluded.new_coach_ok, needs_coach_review = excluded.needs_coach_review, source = excluded.source, sort_order = excluded.sort_order, updated_by = excluded.updated_by;
insert into public.exercises (id, block_type, title, duration_minutes_default, summary, how_to, watch_for, watch_for_required, safety_line, visual_key, difficulty, tags, default_station_equipment, legacy_equipment, progression_of, regression_of, experienced_coach_only, new_coach_ok, needs_coach_review, source, sort_order, updated_by) values ('warm-tojning-gymnaster', 'warmup', 'Töjning — gymnasterna leder', 5, 'Töjning där gymnaster leder varandra eller gruppen — ansvar och igenkända stretch.', '1. Utse ledare (rotera mellan passen).
2. De visar töjningar ni redan kan.
3. Coachen backar upp säkerhet och tid.', 'Ojämn kvalitet — rätta farliga vinklar; ingen ”press” djupare än behagligt.', true, 'Ingen press djupare än behagligt. Rätta farliga vinklar.', 'warm-stretch-athletes', 'intro', array['uppvärmning', 'group', 'equipment-free', 'new-coach-ok']::text[], null, null, null, null, false, true, false, null, 90, 'seed-script') on conflict (id) do update set block_type = excluded.block_type, title = excluded.title, duration_minutes_default = excluded.duration_minutes_default, summary = excluded.summary, how_to = excluded.how_to, watch_for = excluded.watch_for, watch_for_required = excluded.watch_for_required, safety_line = excluded.safety_line, visual_key = excluded.visual_key, difficulty = excluded.difficulty, tags = excluded.tags, default_station_equipment = excluded.default_station_equipment, legacy_equipment = excluded.legacy_equipment, progression_of = excluded.progression_of, regression_of = excluded.regression_of, experienced_coach_only = excluded.experienced_coach_only, new_coach_ok = excluded.new_coach_ok, needs_coach_review = excluded.needs_coach_review, source = excluded.source, sort_order = excluded.sort_order, updated_by = excluded.updated_by;
insert into public.exercises (id, block_type, title, duration_minutes_default, summary, how_to, watch_for, watch_for_required, safety_line, visual_key, difficulty, tags, default_station_equipment, legacy_equipment, progression_of, regression_of, experienced_coach_only, new_coach_ok, needs_coach_review, source, sort_order, updated_by) values ('warm-tojning-coach', 'warmup', 'Töjning — coach leder', 5, 'Coachledd töjning efter eller mitt i uppvärmningen — lugn, förutsägbar stretch.', '1. Led ett kort stretchprogram (ben, höftböjare, axlar, handleder efter behov).
2. Andas lugnt; håll ca 15–30 s per sida där det passar.
3. Håll samma ordning så gruppen känner igen flödet.', 'Studsande stretch; smärta ≠ ”bra”; anpassa för hypermobila gymnaster.', true, 'Studsa inte i stretchen. Smärta är inte målet.', 'warm-stretch-coach', 'intro', array['uppvärmning', 'group', 'equipment-free', 'new-coach-ok']::text[], null, null, null, null, false, true, false, null, 100, 'seed-script') on conflict (id) do update set block_type = excluded.block_type, title = excluded.title, duration_minutes_default = excluded.duration_minutes_default, summary = excluded.summary, how_to = excluded.how_to, watch_for = excluded.watch_for, watch_for_required = excluded.watch_for_required, safety_line = excluded.safety_line, visual_key = excluded.visual_key, difficulty = excluded.difficulty, tags = excluded.tags, default_station_equipment = excluded.default_station_equipment, legacy_equipment = excluded.legacy_equipment, progression_of = excluded.progression_of, regression_of = excluded.regression_of, experienced_coach_only = excluded.experienced_coach_only, new_coach_ok = excluded.new_coach_ok, needs_coach_review = excluded.needs_coach_review, source = excluded.source, sort_order = excluded.sort_order, updated_by = excluded.updated_by;
insert into public.exercises (id, block_type, title, duration_minutes_default, summary, how_to, watch_for, watch_for_required, safety_line, visual_key, difficulty, tags, default_station_equipment, legacy_equipment, progression_of, regression_of, experienced_coach_only, new_coach_ok, needs_coach_review, source, sort_order, updated_by) values ('warm-djurpromenad', 'warmup', 'Djurpromenad', 6, 'Björn, krabba och kanin över golvet — kroppen vaknar utan maxhopp.', '1. Visa björn, krabba och kanin.
2. Gå en led över golvet, ett djur i taget.
3. Byt djur efter varje vända.
4. Håll kön så ingen startar förrän ytan är fri.', 'Handleder och avstånd. Ingen kapplöpning in i nästa.', true, 'Håll avstånd mellan leden. Inga hopp på hårt golv.', 'warm-animals', 'easy', array['uppvärmning', 'group', 'floor', 'new-coach-ok']::text[], null, null, null, null, false, true, false, null, 110, 'seed-script') on conflict (id) do update set block_type = excluded.block_type, title = excluded.title, duration_minutes_default = excluded.duration_minutes_default, summary = excluded.summary, how_to = excluded.how_to, watch_for = excluded.watch_for, watch_for_required = excluded.watch_for_required, safety_line = excluded.safety_line, visual_key = excluded.visual_key, difficulty = excluded.difficulty, tags = excluded.tags, default_station_equipment = excluded.default_station_equipment, legacy_equipment = excluded.legacy_equipment, progression_of = excluded.progression_of, regression_of = excluded.regression_of, experienced_coach_only = excluded.experienced_coach_only, new_coach_ok = excluded.new_coach_ok, needs_coach_review = excluded.needs_coach_review, source = excluded.source, sort_order = excluded.sort_order, updated_by = excluded.updated_by;
insert into public.exercises (id, block_type, title, duration_minutes_default, summary, how_to, watch_for, watch_for_required, safety_line, visual_key, difficulty, tags, default_station_equipment, legacy_equipment, progression_of, regression_of, experienced_coach_only, new_coach_ok, needs_coach_review, source, sort_order, updated_by) values ('warm-fotarbete', 'warmup', 'Fotarbete på stället', 4, 'Lätt fötter på egen ruta — jogg, galopp och små hopp, inte en tävling.', '1. Varje gymnast har en egen ruta, inte en tät klunga.
2. Lätt jogg, galopp och små jämfotahopp på stället.
3. Mjuka landningar. Armarna hjälper balansen.
4. Avsluta med att stå stilla och andas.', 'Hårda landningar och hopp som blir tävling.', true, 'Mjuka landningar. Ingen maxhopp på hårt golv.', 'warm-feet', 'intro', array['uppvärmning', 'group', 'equipment-free', 'new-coach-ok']::text[], null, null, null, null, false, true, false, null, 120, 'seed-script') on conflict (id) do update set block_type = excluded.block_type, title = excluded.title, duration_minutes_default = excluded.duration_minutes_default, summary = excluded.summary, how_to = excluded.how_to, watch_for = excluded.watch_for, watch_for_required = excluded.watch_for_required, safety_line = excluded.safety_line, visual_key = excluded.visual_key, difficulty = excluded.difficulty, tags = excluded.tags, default_station_equipment = excluded.default_station_equipment, legacy_equipment = excluded.legacy_equipment, progression_of = excluded.progression_of, regression_of = excluded.regression_of, experienced_coach_only = excluded.experienced_coach_only, new_coach_ok = excluded.new_coach_ok, needs_coach_review = excluded.needs_coach_review, source = excluded.source, sort_order = excluded.sort_order, updated_by = excluded.updated_by;
insert into public.exercises (id, block_type, title, duration_minutes_default, summary, how_to, watch_for, watch_for_required, safety_line, visual_key, difficulty, tags, default_station_equipment, legacy_equipment, progression_of, regression_of, experienced_coach_only, new_coach_ok, needs_coach_review, source, sort_order, updated_by) values ('tech-ljushopp-satsbrada', 'techniques', 'Ljushopp på satsbräda', 6, 'Ljushopp från satsbräda — grundstuds och hoppteknik med fokus på timing, inte höjd först.', '1. Visa sats → bräda → ljushopp med kontrollerad landning.
2. En i taget; tydlig kö.
3. Cue: timing och rak kropp före höjd.', 'Fel fotisättning på brädan; landning bakom/framför mattan; köhållning så ingen springer in för tidigt.', true, 'En i taget. Ingen springer in förrän landningen är klar.', 'tech-ljushopp-board', 'easy', array['teknik', 'vault', 'new-coach-ok']::text[], '[{"pieceId":"eq-satsbrada","count":1},{"pieceId":"eq-landningsmatta","count":1}]'::jsonb, null, null, null, false, true, false, null, 130, 'seed-script') on conflict (id) do update set block_type = excluded.block_type, title = excluded.title, duration_minutes_default = excluded.duration_minutes_default, summary = excluded.summary, how_to = excluded.how_to, watch_for = excluded.watch_for, watch_for_required = excluded.watch_for_required, safety_line = excluded.safety_line, visual_key = excluded.visual_key, difficulty = excluded.difficulty, tags = excluded.tags, default_station_equipment = excluded.default_station_equipment, legacy_equipment = excluded.legacy_equipment, progression_of = excluded.progression_of, regression_of = excluded.regression_of, experienced_coach_only = excluded.experienced_coach_only, new_coach_ok = excluded.new_coach_ok, needs_coach_review = excluded.needs_coach_review, source = excluded.source, sort_order = excluded.sort_order, updated_by = excluded.updated_by;
insert into public.exercises (id, block_type, title, duration_minutes_default, summary, how_to, watch_for, watch_for_required, safety_line, visual_key, difficulty, tags, default_station_equipment, legacy_equipment, progression_of, regression_of, experienced_coach_only, new_coach_ok, needs_coach_review, source, sort_order, updated_by) values ('tech-ljushopp-trampett', 'techniques', 'Ljushopp på trampett', 6, 'Ljushopp på trampett — tydlig ansats, studs i mitten, sträckt hopp och mjuk landning.', '1. Visa tydlig ansats och studs i mitten av trampetten.
2. Sträckt ljushopp, mjuk landning.
3. En i taget; vänta tills landningen är klar.', 'Ansats för lång/snabb; studs nära kanten; landning utan madrasskydd där det behövs.', true, 'En i taget. Landning på madrass — vänta tills den är klar.', 'tech-ljushopp-trampett', 'easy', array['teknik', 'trampett', 'new-coach-ok']::text[], '[{"pieceId":"eq-trampett","count":1},{"pieceId":"eq-landningsmatta","count":1}]'::jsonb, null, null, null, false, true, false, null, 140, 'seed-script') on conflict (id) do update set block_type = excluded.block_type, title = excluded.title, duration_minutes_default = excluded.duration_minutes_default, summary = excluded.summary, how_to = excluded.how_to, watch_for = excluded.watch_for, watch_for_required = excluded.watch_for_required, safety_line = excluded.safety_line, visual_key = excluded.visual_key, difficulty = excluded.difficulty, tags = excluded.tags, default_station_equipment = excluded.default_station_equipment, legacy_equipment = excluded.legacy_equipment, progression_of = excluded.progression_of, regression_of = excluded.regression_of, experienced_coach_only = excluded.experienced_coach_only, new_coach_ok = excluded.new_coach_ok, needs_coach_review = excluded.needs_coach_review, source = excluded.source, sort_order = excluded.sort_order, updated_by = excluded.updated_by;
